SELECT COUNT(*) FILTER (WHERE order_status = 'canceled')::numeric
       / COUNT(*)
FROM orders;

SELECT COUNT(CASE WHEN order_status = 'canceled' THEN 1 END)
       / COUNT(*)
FROM orders;

SELECT COUNT(*)
FROM orders o
WHERE NOT EXISTS (
  SELECT 1 FROM order_reviews r WHERE r.order_id = o.order_id
);
